const req = $input.first().json;
const secret = req.headers?.['x-accordops-secret'] ?? req.headers?.['X-AccordOps-Secret'];
if (!secret) throw new Error('Missing AccordOps webhook secret');
const body = req.body ?? req;
for (const key of ['organization_id', 'obligation_id', 'observed_value']) {
  if (!body[key]) throw new Error(`Missing required field: ${key}`);
}
return [{
  json: {
    organization_id: String(body.organization_id),
    obligation_id: String(body.obligation_id),
    observed_value: String(body.observed_value).trim(),
    evidence_note: body.evidence_note ? String(body.evidence_note).trim() : null,
    source: String(body.source ?? 'n8n'),
    accordops_secret: String(secret),
  },
}];

const evidence = $('Validate & Normalize Evidence').first().json;
const control = $input.first().json;
const prompt = [
  'You are AccordOps AI evaluating operational evidence against an approved contract control.',
  'Return ONLY valid JSON with keys: compliant (boolean), finding (string), recommended_action (string), confidence (number 0..1).',
  'Be conservative. Never invent missing evidence.',
  `Contract: ${control.contract_title}`,
  `Control: ${control.obligation_title}`,
  `Normalized requirement: ${control.obligation_description}`,
  `Source clause: ${control.source_clause ?? 'Not available'}`,
  `Rule config: ${JSON.stringify(control.rule_config ?? {})}`,
  `Observed value: ${evidence.observed_value}`,
  `Evidence note: ${evidence.evidence_note ?? 'None'}`,
].join('\n');
return [{ json: { ...evidence, control, prompt } }];

const evidence = $('Validate & Normalize Evidence').first().json;
const response = $input.first().json;
const raw = response.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no structured evaluation');
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error('Gemini response was not valid JSON');
}
if (typeof parsed.compliant !== 'boolean') {
  throw new Error('Gemini evaluation is missing compliant boolean');
}
const confidence = Math.max(0, Math.min(1, Number(parsed.confidence ?? 0.65)));
return [{
  json: {
    organization_id: evidence.organization_id,
    obligation_id: evidence.obligation_id,
    source: 'n8n',
    observed_value: evidence.observed_value,
    evidence_note: evidence.evidence_note,
    compliant: parsed.compliant,
    finding: String(parsed.finding ?? 'Evidence evaluated.'),
    recommended_action: String(parsed.recommended_action ?? 'Record the result for human review.'),
    confidence,
    provider: 'gemini',
    model: 'gemini-3.5-flash-lite',
    accordops_secret: evidence.accordops_secret,
    raw_evaluation: { ...parsed, n8n_execution_id: $execution.id },
  },
}];
